102→// ExtractLastCompletedTodo extracts the content of the last completed todo item from tool_input.
103→// This represents the work that was just finished and is used for commit messages.
104→//
105→// When TodoWrite is called in PostToolUse, the NEW list is provided which has the
106→// just-completed work marked as "completed". The last completed item is the most
107→// recently finished task.
108→//
109→// Returns empty string if no completed items exist or JSON is invalid.
110→func ExtractLastCompletedTodo(todosJSON []byte) string {
111→	if len(todosJSON) == 0 {
112→		return ""
113→	}
114→
115→	var todos []todoItem
116→	if err := json.Unmarshal(todosJSON, &todos); err != nil {
117→		return ""
118→	}
119→
120→	// Find the last completed item - this is the work that was just finished
121→	var lastCompleted string
122→	for _, todo := range todos {
123→		if todo.Status == "completed" {
124→			lastCompleted = todo.Content
125→		}
126→	}
