145→// ExtractInProgressTodo extracts the content of the in-progress todo item from tool_input.
146→// This is used for commit messages in incremental checkpoints.
147→//
148→// Priority order:
149→//  1. in_progress item (current work)
150→//  2. first pending item (next work - fallback)
151→//  3. last completed item (final work just finished)
152→//  4. first item with unknown status (edge case)
153→//  5. empty string (no items)
154→//
155→// Returns empty string if no suitable item is found or JSON is invalid.
156→func ExtractInProgressTodo(todosJSON []byte) string {
157→	if len(todosJSON) == 0 {
158→		return ""
159→	}
160→
161→	var todos []todoItem
162→	if err := json.Unmarshal(todosJSON, &todos); err != nil {
163→		return ""
164→	}
165→
166→	if len(todos) == 0 {
167→		return ""
168→	}
169→
170→	// Look for in_progress item first (case-sensitive match)
171→	for _, todo := range todos {
172→		if todo.Status == "in_progress" {
173→			return todo.Content
174→		}
175→	}
176→
177→	// Fall back to first pending item
178→	for _, todo := range todos {
179→		if todo.Status == "pending" {
180→			return todo.Content
181→		}
182→	}
183→
184→	// Fall back to last completed item (represents the work that was just finished)
185→	var lastCompleted string
186→	for _, todo := range todos {
187→		if todo.Status == "completed" {
188→			lastCompleted = todo.Content
189→		}
190→	}
191→	if lastCompleted != "" {
192→		return lastCompleted
193→	}
194→
195→	// If no in_progress, pending, or completed items, but there are items with
196→	// unrecognized status, return first item's content as a fallback (handles edge cases).
197→	if todos[0].Content != "" {
198→		return todos[0].Content
199→	}
200→
201→	return ""
202→}
